// ─── Types ───────────────────────────────────────────────────

export interface MentorLesson {
  id: string;
  title: string;
  duration: string;
  content: string;
  keyPoints: string[];
  practiceTask: string;
  reflectionQuestion: string;
}

export interface MentorModule {
  id: string;
  title: string;
  description: string;
  lessons: MentorLesson[];
}

export interface MentorCourse {
  id: string;
  title: string;
  overview: string;
  modules: MentorModule[];
  totalDuration: string;
  learningDuration: string;
  difficulty: "Beginner" | "Intermediate" | "Advanced";
}

export interface MentorPersona {
  id: string;
  name: string;
  title: string;
  tagline: string;
  personality: string;
  avatar: string;
  initials: string;
  isMaster?: boolean;
  envTheme: { bg: string; accent: string; mood: string };
  voiceConfig: { pitch: number; rate: number; voiceHint: string };
  specialties: string[];
  greeting: string;
  encouragement: string[];
  course: MentorCourse;
}

export interface MentorCategory {
  id: string;
  slug: string;
  label: string;
  tagline: string;
  description: string;
  icon: LucideIcon;
  color: string;
  gradient: string;
  mentors: MentorPersona[];
}

// ─── Helper: generate lesson responses ───────────────────────

function mentorRespond(mentorName: string, topic: string): string[] {
  return [
    `Great question! Let me walk you through ${topic} step by step.`,
    `${mentorName} here. ${topic} is one of my favorite subjects to teach.`,
    `You're making excellent progress. Let me explain ${topic} in a way that clicks.`,
  ];
}

