// ─── Merged Categories ──────────────────────────────────────

// Strategic order: "Build the human first. Then build the skill."
// Tier 1 — Core human foundation & future-proof thinking
// Tier 2 — Technical literacy, creativity & communication
// Tier 3 — Business, innovation & applied leadership
// Tier 4 — Specialized domains & emerging fields

const _allUnordered: MentorCategory[] = [
  ...baseMentorCategories,
  ...newMentorCategories,
];

const _bySlug = (slug: string) =>
  _allUnordered.find((c) => c.slug === slug)!;

export const mentorCategories: MentorCategory[] = [
  // ── Tier 1: Human foundation & core thinking ──
  _bySlug("personal-growth"),     // Build the human first
  _bySlug("philosophy"),          // Critical thinking — the mind's operating system
  _bySlug("ai-skills"),           // Skills for the AI Era — future-proof literacy
  _bySlug("systems"),             // Systems Thinking — problem-solving & decision-making

  // ── Tier 2: Technical, creative & communication skills ──
  _bySlug("coding"),              // Core technical literacy
  _bySlug("design"),              // Creativity meets problem-solving
  _bySlug("data-science"),        // Analytical & data fluency
  _bySlug("writing"),             // Communication & Writing
  _bySlug("speaking"),            // Public Speaking & Influence

  // ── Tier 3: Business, innovation & leadership ──
  _bySlug("entrepreneurship"),    // Decision-making, building, leading
  _bySlug("innovation"),          // Open Innovation & research
  _bySlug("human-ai"),            // Human-AI Collaboration
  _bySlug("creator"),             // Digital Craft & Creator Economy

  // ── Tier 4: Specialized & emerging domains ──
  _bySlug("health"),              // Health & Longevity
  _bySlug("climate"),             // Climate & Sustainability
  _bySlug("agriculture"),         // Future of Agriculture
];

// ─── Helpers ─────────────────────────────────────────────────

export function getMentorCategory(slug: string): MentorCategory | undefined {
  return mentorCategories.find((c) => c.slug === slug);
}

export function getMentor(categorySlug: string, mentorId: string): MentorPersona | undefined {
  const cat = getMentorCategory(categorySlug);
  return cat?.mentors.find((m) => m.id === mentorId);
}

export function getAllMentorCount(): number {
  return mentorCategories.reduce((sum, c) => sum + c.mentors.length, 0);
}

export function getAllLessonCount(): number {
  return mentorCategories.reduce(
    (sum, c) => sum + c.mentors.reduce(
      (s, m) => s + m.course.modules.reduce(
        (ls, mod) => ls + mod.lessons.length, 0
      ), 0
    ), 0
  );
}
